//! 🔢️ A declared unit variant is constructed only after the actual original discriminator has completed bounded matching.
use super::*;
use crate::{retirement::RetireOwned,retained_clone::RetainedCloneClose,owned::{NativeReceiver,NativeAdvanceSelection},OriginalEffectReply,OriginalEffectReplyComplete};
use std::mem::ManuallyDrop;
pub trait NativeUnitVariants:RetireOwned{fn variant_spec()->NativeVariantSpec;fn from_variant_index(index:usize)->Result<Self,ValueError>where Self:Sized;}
pub struct NativeUnitEnumReceiver<I:NativeValueSource+?Sized,T:NativeUnitVariants>{selector:NativeVariantSelector<I>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,closing:bool}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>NativeUnitEnumReceiver<I,T>{pub fn new()->Self{Self{selector:NativeVariantSelector::new(T::variant_spec()),output:ManuallyDrop::new(None),retirement:Default::default(),closing:false}}}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>NativeReceiver<I,T>for NativeUnitEnumReceiver<I,T>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}self.selector.validate_input(input)?;if self.selector.result().is_some(){Ok(fixed(0))}else{self.selector.demands(input,body,maximum_work_units)}}
 fn select_advance(&self,input:RetainedCloneRef<'_,I>,body:usize,maximum_work_units:u64)->Result<NativeAdvanceSelection,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}self.selector.validate_input(input)?;if self.selector.result().is_some(){Ok(NativeAdvanceSelection::Local{work:1})}else{self.selector.select_advance(input,body,maximum_work_units)}}
 fn advance_nested(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->crate::RetainedWorkPoll<RetainedCloneStep,OriginalReceivingPrimary>{if self.closing||self.output.is_some()||self.selector.result().is_some(){return crate::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}self.selector.advance_nested(input,control,body,maximum_work_units,g)}
 fn advance_local<'reply>(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{
  let result:Result<Option<RetainedCloneStep>,OriginalReceivingPrimary>=(||{let d=self.demands(input,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(Some(RetainedCloneStep::Progress(Default::default())))}
   let Some(selected)=self.selector.result()else{return self.selector.advance_local(input,body,effect)};
   if !effect.performed(1)?{return Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native unit variant action exceeded its original work").into())}
   let value=T::from_variant_index(selected.index).map_err(|e|e.with_retained_progress(receipt(fixed(0))))?;*self.output=Some(value);Ok(Some(RetainedCloneStep::Complete(receipt(fixed(0)))))})();
  Ok(match result{Ok(Some(step))=>reply.complete(Ok(step)),Ok(None)=>reply.pending(),Err(error)=>reply.complete(Err(error))})
 }
 fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 semio_framework_value_native_receiver_protocol::native_owned_output!(T,invalid);
 semio_framework_value_native_receiver_protocol::native_receiver_close_start!(closing);
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.selector.terminal_is_empty(){return self.selector.close_demands(body)}self.retirement.next_owner_demands::<T>(self.output.is_some(),&None,body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if !self.selector.terminal_is_empty(){return self.selector.close_work_demand(body)}self.retirement.next_owner_work::<T>(self.output.is_some(),&None,body)}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementPoll{use crate::RetainedWorkPoll::Complete;let g=effect.grant();if self.terminal_is_empty(){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return Complete(RetainedWorkOutcome{result:Err(e.into()),work:0})};if !retained_clone_grant_admits(g,d){return Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}if !self.selector.terminal_is_empty(){return self.selector.close_step(&mut effect.nested(g)).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){return self.retirement.step_granted(effect).map(|s|RetainedCloneStep::Progress(s.progress()))}let turn=self.retirement.begin_granted(&mut self.output,effect);Complete(RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work})}
 fn terminal_is_empty(&self)->bool{self.selector.terminal_is_empty()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<I:NativeValueSource+?Sized,T:NativeUnitVariants>Drop for NativeUnitEnumReceiver<I,T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native unit variant requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.output);}}}}
